package main

import (
	"fmt"
)

func main() {
	var n, k int
	var s string
	fmt.Scan(&n, &k, &s)

	b := make([]int, 105)

	for i := 0; i < n; i++ {
		b[s[i]-'0']++
	}

	flag := 0
	for i := 40; i <= 100; i++ {
		if b[i] > k {
			flag = 1
		}
	}

	if flag == 1 {
		fmt.Println("NO")
	} else {
		fmt.Println("YES")
	}
}

